scripts.元真对话.txt:
//和元真对话
	
	If ($Talkyuantong == 0) @TalkyuanzhenA;
	If ($Talkyuantong == 1) @TalkyuanzhenB;
		
@TalkyuanzhenA:
	If ($Talkyuanzhen == 0) @Talkyuanzhen0;
	If ($Talkyuanzhen == 1) @Talkyuanzhen1;
 @Talkyuanzhen0:
	Say("元真：你们别来捣乱，小心弄伤了我的徒弟。", 0);
	Say("独孤剑：徒弟？大师年纪轻轻就有徒弟了？", 1);
	Say("元真：你没看见地上吗？这就是我的二徒弟猪悟能，这是三徒弟沙悟净，你们不要踩到他们了。", 0);
	Say("独孤剑：大师便是唐僧了？", 2);
	Say("元真：贫僧法号“三藏”。", 0);
	Say("张琳心：咦，三藏大师，你的大徒弟孙悟空呢？", 21);
	Say("元真：你们不要气我好不好？我的大徒弟孙行者被师兄元通抢走了。我又打不过他，以后遇到妖怪谁来救我……", 0);
	Say("张琳心：独孤大哥，我们帮他把大徒弟拿回来好不好？", 21);
	Say("独孤剑：好吧！", 2);
	Assign($Talkyuanzhen, 1);
	Memo("独孤剑和张琳心来到少林寺，遇到和尚元真，得知元真的泥人被师兄元通抢走，决定帮他夺回。");
	Return;
	
 @Talkyuanzhen1:	
	Say("元真：八戒，沙僧，给我拿下这两个妖精。", 0);
	Return;
	
@TalkyuanzhenB:
	If ($Talkyuanzhen == 2) @TalkyuanzhenC;
	
	Say("独孤剑：大师，这个可是你的大徒弟？", 1);
	Say("元真：行者？你们给我把行者找回来了。太好了！", 0);
	Say("张琳心：小师父，知道在哪儿可以找到无虚大师吗？", 21);
	Say("元真：你们找师叔祖啊？看在你们替我找回行者的份上，我就告诉你们吧。师叔祖在达摩堂后面的密室里闭关练功，不准人去打扰他，你们可别说是我说的哟。……密室外面还有他的诗。", 0);
	DelGoods("Goods407_泥人.ini"); 
	Assign($Talkyuanzhen, 2);
	Assign($Event, 380);
	Memo("从元通那里找回泥人，还给元真，元真告诉二人，无虚大师在达摩堂。");
	Return;
	
@TalkyuanzhenC:
	Say("元通：取西经，打妖精，牛头马怪，现原形……", 0);
	Return;

scripts.元通对话.txt:
//和元通对话
	
	If ($Event == 370) @Event370;
	If ($Event >= 410) @Event410;

	Say("元通：那猪八戒为什么也是秃头呢？", 0);
	Return;
	
@Event370:	
	
	If ($Talkyuanzhen == 0) @TalkyuantongA;
	If ($Talkyuanzhen == 1) @TalkyuantongB;

@TalkyuantongA:
	Say("元通：猴头！看你怎么逃得出佛祖的五指山！", 0);
	Return;
	
@TalkyuantongB:
	If ($Talkyuantong == 1) @Talkyuantong1;
	
	Say("独孤剑：你就是元通？", 1);
	Say("元通：你们是什么人？", 0);
	Say("独孤剑：你是不是抢了你师弟的泥人？如果你不归还给他，他禀明师傅，说你以大欺小，难道你不怕受寺规处罚？", 1);
	Say("元通：元真他敢……要还他可以，你们先得解答我一个问题。", 0);
	Say("独孤剑：好，你说吧。", 1);
	Say("元通：我是和尚，孙行者也是和尚。为什么我是秃头，他却不是秃头呢？", 0);
	
	Choose("独孤剑：这……","A 解答","B 不知道", $Chooseyuantong);
	If ($Chooseyuantong == 0) @Choose0;
	If ($Chooseyuantong == 1) @Choose1;
  @Choose0:
	Say("独孤剑：因为他六根未净，而大师却勘破红尘了呀！", 2);
	Say("元通：……不错！好吧，泥人你拿走吧！", 0);
	AddGoods("Goods407_泥人.ini"); 
	Assign($Talkyuantong, 1);
	Return;
  @Choose1:
  	Say("独孤剑：他只是一只猴子，何必这么认真呢？", 8);
  	Say("元通：……不错！好吧，泥人你拿走吧！", 0);
	AddGoods("Goods407_泥人.ini"); 
	Assign($Talkyuantong, 1);
	Return;
	
 @Talkyuantong1:
	Say("元通：那猪八戒为什么也是秃头呢？", 0);
	Return;


	
@Event410:
	Say("和尚：无相师叔居然是五色教的奸细，真是没想到！", 0);

scripts.无智对话.txt:
// 和无智对话

	If ($Event >= 410) @Event410;

	If ($Talkwuzhi == 0) @Talkwuzhi0;
	If ($Talkwuzhi == 1) @Talkwuzhi1;
	
@Talkwuzhi0:
	Say("无智：阿弥陀佛！这位女施主，少林向来谢绝女客入访，你如何进来？", 0);
	Say("张琳心：又来了。独孤哥哥，你看我的。", 21);
	Say("张琳心：大师此言差矣！我且问大师：心生念，念生佛，无心无念，可曾有佛？", 21);
	Say("无智：阿弥陀佛！施主错了。佛自在自有，自枯自荣，岂是我等凡心所生！", 0);
	Say("张琳心：这个……那我再问大师：心可有男女之别，佛岂对众生不等。", 23);
	Say("无智：问得好。若在佛看来，自当众生无差。但我等皆为凡胎肉体，自然做不到心中无垢。少林所以门规森严，便是勉力修行之人拂去心中的尘垢，方能体悟我佛包容万物的境界。", 0);
	Say("张琳心：这个……", 23);
	Say("独孤剑：多谢大师指点。", 1);
	Say("无智：施主明白了吗？老衲还请施主速速离去。", 0);
	Say("张琳心：什么人……", 25);
	Sleep(500);
	SetNpcDir("无智", 4);
	Say("无智：咦？", 0);
	Sleep(500);
	Say("张琳心：独孤哥哥，快走！", 21);
	Say("独孤剑：啊？", 8);
	Assign($Talkwuzhi, 1);
	Return;
	
@Talkwuzhi1:	
	Say("无智：阿弥陀佛！施主原来在骗老衲。", 0);
	SetNpcDir("无智", 0);
	Return;
	
@Event410:
	Say("无智：怀慈悲心，达光明境界；怀平常心，致不二法门。", 0);
	Say("无智：南无阿弥陀佛！", 0);
	Return;

scripts.张琳心对话.txt:
// 张琳心的同伴对话

	If ($Event == 370) @Event370;
	If ($Event == 380) @Event380;
	If ($Event == 390) @Event390;
	If ($Event == 400) @Event400;
	If ($Event == 410) @Event410;
	If ($Event == 420) @Event420;
	Return;
	
@Event370:
	If ($Talkzhikeseng == 0) @Talk0;
	If ($Talkzhikeseng == 1) @Talk1;
	
@Talk0:
	Say("张琳心：这少林寺庄严肃穆，果然不同与其它寺庙。", 21);
	Return;
@Talk1:	
	If ($Talkwuzhi == 1) @Talk2;
	
	Say("独孤剑：琳儿，你从哪学来这些大道理？", 2);
	Say("张琳心：呵呵，我只是顺口胡诌。这个和尚张口一个阿弥陀佛，闭口一个佛经有云——一看便是个芋头大木鱼。", 21);
	Say("独孤剑：你真是精灵古怪！", 2);
	Say("张琳心：走吧，我们进去找老和尚！", 21);
	Return;
		
@Talk2:
	Say("张琳心：少林高僧果然是佛学精湛……",21);
	Return;
			
@Event380:
	Say("张琳心：我们去达摩堂找无虚大师吧。", 21);			
	Say("独孤剑：好。", 1);
	Return;
	
@Event390:	
	Say("张琳心：走，独孤哥哥。我们四处看看，也许能找到线索。", 21);	
	Return;
	
@Event400:
	Say("独孤剑：那黄剑堂堂主是谁呢？", 1);
	Say("张琳心：独孤哥哥，你别犯愁，我自有妙计引他出来，我们先去找无虚大师吧。", 21);
	Return;
	
@Event410:
	Say	("张琳心：独孤哥哥，我们去藏经阁拜访无穷大师吧，说不定有什么意想不到的收获呢。", 21);
	Return;
	
@Event420:
	Say("张琳心：我们下山吧！", 21);
	Return;

scripts.知客僧对话.txt:
//	和知客僧对话

	If ($Event == 370) @Event370;
	
	Say("知客僧：心生念，念生佛……色即是空，佛经有云……为何，为何……", 0);
	Return;
	
@Event370:
	If ($Talkzhikeseng == 0) @Talk0;
	If ($Talkzhikeseng == 1) @Talk1;
	
@Talk0:
	Say("知客僧：阿弥陀佛！两位施主请留步。", 0);
	Say("独孤剑：大师，在下衡山独孤剑，有要事求见方丈大师。", 1);
	Say("知客僧：阿弥陀佛！施主稍候，容小僧通禀……只是这位女施主……", 0);
	Say("张琳心：女施主也是施主，怎么了！", 21);
	Say("知客僧：阿弥陀佛！请恕小僧无礼——少林寺向来谢绝女客入访，这是数百年来的规矩。", 0);
	Say("张琳心：这倒奇了，没听说过天下的寺庙有不许女客进入的。", 23);
	Say("知客僧：阿弥陀佛！少林寺乃是佛门清修之地，非比寻常的寺庙。", 0);
	Say("张琳心：你一口一个阿弥陀——佛，不知拜的是哪门子的佛？", 23);
	Say("独孤剑：琳儿，不可无礼。", 1);
	Say("知客僧：阿弥陀佛！当然是大慈大悲我佛如来。", 0);
	Say("张琳心：心生念，念生佛，无心无念，可曾有佛？", 21);
	Say("知客僧：阿弥陀佛！佛经有云“佛在心中”，无心……当是无佛吧。", 0);
	Say("张琳心：那我再问你，念可有男女之别？心可分贵贱高低？佛岂对众生另看一眼？", 21);
	Say("知客僧：阿弥陀佛！佛经有云“众生平等”，这个……", 0);
	Say("张琳心：酒色皮囊、男女之别，皆是蠢物。佛说四大皆空，色即是空，空即是色，怎有男女之分呢？", 21);
	Say("知客僧：这……阿弥……", 0);
	Say("张琳心：不要阿弥陀佛了，大师佛学精湛，可否给小女子解释这条不近人情的寺规？", 23);
	Say("知客僧：这，这……心生念，念生佛……佛经有云：色即是空，空即是色……为何，为何……", 0);
	Assign($Talkzhikeseng, 1);
	NpcGoto("知客僧", 5, 53);
	SetNpcDir("知客僧", 3);
	Say("张琳心：独孤哥哥，我们进去吧！", 21);
	Return;
@Talk1:	
	Say("知客僧：心生念，念生佛……色即是空，佛经有云……为何，为何……", 0);
	Return;

